//! The console's register defaults by SDK version (`sceAgcGetRegisterDefaults*`), converted
//! from AnyPS5's `core/libs/prx/libSceAgc/Command/include/RegisterDefaultsData.hpp`, with the
//! tables it derives in code applied (internal V13 bank 1, public V11 and V12 bank 0).

#![allow(clippy::all)]

/// One bank of a defaults table: its registers and the indices the pointer table names.
pub struct Bank {
    pub registers: &'static [(u32, u32)],
    /// Which source table the registers are, so versions sharing one share its copy.
    pub table: usize,
    pub pointers: &'static [u16],
}

/// A defaults table: four banks and the type entries (three dwords each).
pub struct Table {
    pub banks: [Option<Bank>; 4],
    pub types: &'static [u32],
}

